import { useMemo } from 'react';
import { useLocation, useNavigate, useParams } from 'react-router-dom';
import { useMuseumConfig } from '../../config/ConfigProvider';
import type { ResourceConfig } from '../../config/schema';
import { listStateKeys, useScrollRestoration, useSessionState } from '../../shared/listState';
import { sortByKindThenYear } from './resourceGroups';

/**
 * 类型筛选：顺序与列表排布一致（图片 → 文档 → 视频 → 模型），
 * 免得"筛选项的先后"和"卡片的先后"对不上。中类的名字与抽屉、徽标统一用「文档」。
 */
export const kindFilters: Array<{ value: ResourceConfig['kind'] | 'all'; label: string }> = [
  { value: 'all', label: '全部' },
  { value: 'image', label: '图片' },
  { value: 'pdf', label: '文档' },
  { value: 'video', label: '视频' },
  { value: 'model', label: '模型' },
];

/**
 * 视图：平铺总览 / 按策展专辑。同一份数据的两种排布，不复制数据。
 * （按年代的那一版已按现场要求去掉：一排排年份标签在手机上占地方，且"同类里按年代"已经在组内生效。）
 */
export const views = [
  { value: 'grid', label: '总览' },
  { value: 'collection', label: '专辑' },
] as const;
export type ArchiveView = (typeof views)[number]['value'];

export const UNCATALOGUED_LABEL = '未编入专辑';

export interface ArchiveGroup {
  key: string;
  label: string;
  summary: string;
  items: ResourceConfig[];
}

/**
 * 档案列表的全部状态与派生数据（筛选、检索、分组、滚动恢复、详情翻页）。
 *
 * 为什么抽出来：档案页要出两套结构（旧壳一套、`?ui=next` 一套），
 * 但"筛什么、怎么排、从哪来回哪去"只能有一份实现——两份实现迟早会在
 * 搜索字段或排序规则上悄悄分叉，而这两种分叉在手机上都表现为"搜不到东西"。
 *
 * 行为与抽取前逐字一致（sessionStorage 的键都没改，新旧两套结构共享同一份筛选状态）。
 */
export function useArchiveList() {
  const { resourceId } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const { config, repository } = useMuseumConfig();
  // 筛选/视图写进 sessionStorage：从资料详情返回时，列表还是离开前那一屏，不会白筛一遍。
  const [query, setQuery] = useSessionState('archive.query', '');
  const [kind, setKind] = useSessionState<ResourceConfig['kind'] | 'all'>('archive.kind', 'all');
  const [view, setView] = useSessionState<ArchiveView>('archive.view', 'grid');
  const selected = resourceId ? repository.getResource(resourceId) : undefined;
  // 只有列表在显示时才恢复/记录滚动位置；详情页有自己的滚动。
  const saveScroll = useScrollRestoration(listStateKeys.archive, !selected);
  const openResource = (id: string) => {
    // 先记一次位置再跳：进详情时列表子树会在同一个提交里被替换，之后再读 scrollTop 可能已经是 0。
    saveScroll();
    navigate(`/archive/${id}`);
  };

  const resources = useMemo(() => {
    const normalized = query.trim().toLocaleLowerCase();
    const matched = config.resources.filter(resource => {
      const matchesKind = kind === 'all' || resource.kind === kind;
      // 搜索覆盖标题、说明与**原始文件名/路径**：查"图纸""核心物项""1980"这类线索时不需要知道站内命名。
      const haystack = `${resource.title}${resource.description}${resource.source?.path ?? ''}${resource.source?.dossier ?? ''}`.toLocaleLowerCase();
      const matchesQuery = !normalized || haystack.includes(normalized);
      return matchesKind && matchesQuery;
    });
    // 平铺「总览」按类型排（图片 → 图纸 → 视频），与设备页的资料抽屉同一套顺序；
    // 专辑视图的组内次序也跟着变成"同类里再按年代"。
    return sortByKindThenYear(matched);
  }, [config.resources, kind, query]);

  const grouped = useMemo(() => {
    const groups: ArchiveGroup[] = config.collections.map(collection => ({
      key: collection.id,
      label: collection.label,
      summary: collection.summary,
      items: resources.filter(resource => resource.collectionIds.includes(collection.id)),
    }));
    const loose = resources.filter(resource => resource.collectionIds.length === 0);
    if (loose.length) groups.push({ key: 'none', label: UNCATALOGUED_LABEL, summary: '', items: loose });
    return groups.filter(group => group.items.length > 0);
  }, [config.collections, resources]);

  // 详情态的 props：两套结构都把它整包交给同一个 ResourceViewer，
  // 于是"从哪来回哪去""同类型左右翻阅"的行为只有一处实现。
  const sourcePath = (location.state as { pathname?: unknown } | null)?.pathname;
  // 同类型的一批资料：图片查看器据此做左右滑动翻阅（不跨类型混排，行为可预期）。
  const siblings = selected ? resources.filter(item => item.kind === selected.kind) : [];
  const index = selected ? siblings.findIndex(item => item.id === selected.id) : -1;
  const goTo = (offset: number) => {
    const target = siblings[index + offset];
    if (!target) return;
    saveScroll();
    // replace：连续翻看不把历史记录堆满；带上原 state，"返回"仍然回到进来时的列表/设备页。
    navigate(`/archive/${target.id}`, { replace: true, state: location.state });
  };
  const viewer = selected
    ? {
      resource: selected,
      onBack: () => navigate(typeof sourcePath === 'string' && sourcePath.startsWith('/') ? sourcePath : '/archive'),
      siblings: siblings.length > 1 && index >= 0
        ? { position: `${index + 1} / ${siblings.length}`, prev: siblings[index - 1], next: siblings[index + 1], onGo: goTo }
        : undefined,
    }
    : undefined;

  return { config, repository, query, setQuery, kind, setKind, view, setView, resources, grouped, selected, viewer, saveScroll, openResource };
}
