import { lazy, Suspense, useState } from 'react';
import { ArrowLeft, Box, Download, RefreshCw } from 'lucide-react';
import type { ResourceConfig } from '../../config/schema';
import { resolveAssetUrl } from '../../config/loadConfig';
import { ImageViewer } from './ImageViewer';
import './archive.css';

// pdf.js 阅读器与三维查看器都很重，各自懒加载。
const PdfViewer = lazy(() => import('./PdfViewer'));
const ModelResourceViewer = lazy(() => import('../devices/ModelResourceViewer'));

/**
 * 资料查看器：只负责"把这份资料显示出来"——页面里只有标题栏 + 资料本体。
 * 编目信息（年代/事件/归属/专辑/来源）不在这里展示：资料页是"看东西"的地方，
 * 详细信息留给资料列表（抽屉/档案页）的徽标与筛选，避免在右侧再立一根信息边栏把画面挤窄。
 */
/** 同一批（同类型）资料的前后项：图片查看器用它做左右滑动/方向键翻阅。 */
export interface ResourceSiblings {
  /** 形如「3 / 6」。 */
  position?: string;
  prev?: ResourceConfig;
  next?: ResourceConfig;
  /** -1 = 上一项，1 = 下一项。 */
  onGo(offset: number): void;
}

export function ResourceViewer({ resource, onBack, siblings }: {
  resource: ResourceConfig;
  onBack(): void;
  siblings?: ResourceSiblings;
}) {
  const [videoFailed, setVideoFailed] = useState(false);
  const url = resolveAssetUrl(resource.url);
  return (
    <section className="resource-page" aria-label={`${resource.title}预览`}>
      <header className="page-header"><button type="button" aria-label="返回" onClick={onBack}><ArrowLeft /></button><strong>{resource.title}</strong><span /></header>
      <div className="resource-stage">
        {resource.kind === 'image' && (
          <ImageViewer
            src={url}
            alt={resource.title}
            position={siblings?.position}
            hasPrev={Boolean(siblings?.prev)}
            hasNext={Boolean(siblings?.next)}
            onPrev={siblings ? () => siblings.onGo(-1) : undefined}
            onNext={siblings ? () => siblings.onGo(1) : undefined}
            prevSrc={siblings?.prev ? resolveAssetUrl(siblings.prev.url) : undefined}
            nextSrc={siblings?.next ? resolveAssetUrl(siblings.next.url) : undefined}
          />
        )}
        {resource.kind === 'video' && !videoFailed && <video src={url} poster={resource.poster ? resolveAssetUrl(resource.poster) : undefined} controls playsInline preload="metadata" onError={() => setVideoFailed(true)} />}
        {resource.kind === 'video' && videoFailed && <div className="media-fallback" role="alert"><strong>视频加载失败</strong><button type="button" onClick={() => setVideoFailed(false)}><RefreshCw />重试</button><a href={url} download><Download />下载视频</a></div>}
        {resource.kind === 'pdf' && <Suspense fallback={<p className="viewer-loading">文档加载中</p>}><PdfViewer url={url} /></Suspense>}
        {resource.kind === 'model' && <Suspense fallback={<div className="model-resource"><Box size={58} /><strong>三维模型资料</strong><span>正在启动三维查看器</span></div>}><ModelResourceViewer resource={resource} /></Suspense>}
      </div>
    </section>
  );
}
